    public MainPage(){Title=ProductBrand.Name;BackgroundColor=Color.FromArgb("#f4f8fa");WrapPage(this,_body);}
    protected override async void OnAppearing(){base.OnAppearing();await Run(async()=>{_events=await _store.LoadAsync();_event=_events.FirstOrDefault(x=>x.Id==_event?.Id)??_events.FirstOrDefault();Draw();});}
    private async Task Run(Func<Task> work){try{await work();}catch(Exception e){await DisplayAlertAsync("Please check",e.Message,"OK");}}
    private static Label Label(string text,int size=16,bool bold=false)=>new(){Text=text,FontSize=size,FontAttributes=bold?FontAttributes.Bold:FontAttributes.None,TextColor=Color.FromArgb("#142d39")};
    private Button Button(string text,Func<Task> action)=>new(){Text=text,FontSize=16,MinimumHeightRequest=48,Padding=12,BackgroundColor=Color.FromArgb(ProductBrand.Accent),TextColor=Colors.White,CornerRadius=8,Command=new Command(async()=>await Run(action))};
    private static Entry Entry(string placeholder,string text="")=>new(){Placeholder=placeholder,Text=text,MinimumHeightRequest=44,PlaceholderColor=Color.FromArgb("#526773"),TextColor=Color.FromArgb("#142d39"),BackgroundColor=Colors.White};
    private void Draw()
    {
        _body.Clear();_body.Add(Label(ProductBrand.Tagline,28,true));_body.Add(Label("Private testing edition · Local plans work offline. Sharing uses the online workspace.",14));
        var picker=new Picker {Title="Choose your event",ItemsSource=_events.Select(x=>x.Name).ToList(),SelectedIndex=_event is null?-1:_events.FindIndex(x=>x.Id==_event.Id)};
        picker.SelectedIndexChanged+=(_,_)=>{if(picker.SelectedIndex>=0){_event=_events[picker.SelectedIndex];Draw();}};_body.Add(picker);
        _body.Add(Button(ProductBrand.NewEvent,()=>EventEditor()));

        if(_event is null){_body.Add(Label("Create your first event to start with a useful template."));return;}
        _body.Add(Label(_event.Name,24,true));_body.Add(Label($"{_event.Type} · {_event.Start:dd MMM yyyy} – {_event.End:dd MMM yyyy} · {_event.Location}"));
        switch(_tab){case "Running order":case "Day plan":DrawTimeline();break;case "Bands & stages":DrawLineup();break;case "Daily critical path":DrawCritical();break;case "Checklists":DrawTasks();break;case "Suppliers":DrawSuppliers();break;case "Share & import":DrawTransfer();break;case "Online workspace":DrawOnline();break;default:DrawOverview();break;}
    }
    private void DrawOverview(){var e=_event!;_body.Add(Label($"{e.Tasks.Count(x=>x.Done)} / {e.Tasks.Count} tasks complete · {e.Timeline.Count} moments"));_body.Add(Label($"Budget: {e.Currency} {e.Budget:N2} · Committed: {e.Currency} {e.Suppliers.Sum(s=>s.Cost):N2}"));_body.Add(Button("Edit event details",()=>EventEditor(e)));foreach(var m in e.Timeline.OrderBy(x=>x.Day+x.Time).Take(6)){_body.Add(Label($"{m.Time:hh\\:mm}  {m.Title}",18,true));_body.Add(Label($"{m.Who} · {m.Status}",14));}}
