        form.Add(name);form.Add(type);form.Add(Label("First day"));form.Add(start);form.Add(Label("Final day"));form.Add(end);form.Add(location);form.Add(currency);form.Add(budget);form.Add(zone);form.Add(notes);
        var questions=new VerticalStackLayout {Spacing=12};var dayCount=Entry("How many event days?",((existing?.End.Date-existing?.Start.Date)?.Days+1??1).ToString());dayCount.Keyboard=Keyboard.Numeric;var stages=Entry("How many stages?",(existing?.Setup.Stages??1).ToString());stages.Keyboard=Keyboard.Numeric;var bands=new VerticalStackLayout {Spacing=10};var bandInputs=new List<Entry>();var guests=Entry("Expected guests / attendees",(existing?.Setup.Guests??0).ToString());guests.Keyboard=Keyboard.Numeric;
        void DrawBandQuestions(){bands.Clear();bandInputs.Clear();var n=int.TryParse(dayCount.Text,out var count)?Math.Clamp(count,1,14):1;end.Date=(start.Date??DateTime.Today).AddDays(n-1);for(int i=0;i<n;i++){var input=Entry($"Day {i+1}: how many bands in total?",(existing?.Setup.BandsPerDay.ElementAtOrDefault(i) is int known&&known>0?known:type.SelectedItem?.ToString()=="Festival"?6:3).ToString());input.Keyboard=Keyboard.Numeric;bandInputs.Add(input);bands.Add(Label(input.Placeholder));bands.Add(input);}}
