    private void DrawLineup()
    {
        var e=_event!;
        _body.Add(Label("Bands & stages",24,true));
        _body.Add(Button("Add a band / stage slot",()=>MomentEditor()));
        foreach(var day in e.Timeline.Where(x=>x.Kind is "Performance" or "Soundcheck" or "Changeover").GroupBy(x=>x.Day.Date).OrderBy(x=>x.Key))
        {
            _body.Add(Label(day.Key.ToString("dddd dd MMM"),22,true));
            foreach(var stage in day.GroupBy(x=>x.Location).OrderBy(x=>x.Key))
            {
                _body.Add(Label(string.IsNullOrWhiteSpace(stage.Key)?"Stage to assign":stage.Key,19,true));
                foreach(var slot in stage.OrderBy(x=>x.Time))
                {
                    _body.Add(Label($"{slot.Time:hh\\:mm} · {slot.Kind} · {slot.Artist} · {slot.Title}"));
                    _body.Add(Label($"{slot.Duration} min · {slot.Who} · {slot.Status}",14));
                    _body.Add(Button("Edit slot",()=>MomentEditor(slot)));
                }
            }
        }
        _body.Add(Label("Use Daily critical path to reorder each stage's day and review dependencies.",14));
    }
    private void DrawTimeline(){var e=_event!;_body.Add(Button("Add a moment",()=>MomentEditor()));foreach(var c in EventStore.Conflicts(e))_body.Add(Label("Check overlap: "+c,14,true));foreach(var m in e.Timeline.OrderBy(x=>x.Day+x.Time)){_body.Add(Label($"{m.Day:dd MMM} · {m.Time:hh\\:mm} · {m.Duration} min",14));_body.Add(Label(m.Title,19,true));_body.Add(Label($"{m.Who} · {m.Track} · {m.Location} · {m.Status}"));if(m.Notes.Length>0)_body.Add(Label(m.Notes,14));_body.Add(Button("Edit moment",()=>MomentEditor(m)));_body.Add(Button(m.Status=="Complete"?"Reopen":"Mark complete",async()=>{m.Status=m.Status=="Complete"?"Planned":"Complete";await _store.SaveAsync(e);Draw();}));}}
    private async Task MomentEditor(Moment? m=null){var e=_event!;var p=new ContentPage {Title=ProductBrand.IsLive?"Running order":"Day plan"};var form=new VerticalStackLayout {Padding=20,Spacing=12};var title=Entry("What is happening?",m?.Title??"");var who=Entry("Responsible person",m?.Who??"");var day=new DatePicker {Date=m?.Day??e.Start,MinimumDate=e.Start,MaximumDate=e.End,Format="dd/MM/yyyy"};var time=new TimePicker {Time=m?.Time??TimeSpan.FromHours(9),Format="HH:mm"};var duration=Entry("Duration (minutes)",(m?.Duration??30).ToString());duration.Keyboard=Keyboard.Numeric;var show=ProductBrand.IsLive;var artist=Entry("Band / artist",m?.Artist??"");artist.IsVisible=show;var kind=new Picker {Title="Slot type",ItemsSource=new[]{"Operations","Performance","Soundcheck","Changeover"},SelectedItem=m?.Kind??"Operations"};var programme=new Switch {IsToggled=m?.Public??false};var parents=e.Timeline.Where(x=>x.Id!=m?.Id).ToList();var dependency=new Picker {Title="Depends on",ItemsSource=new[]{"No dependency"}.Concat(parents.Select(x=>x.Title)).ToList(),SelectedIndex=m?.DependsOn is Guid parentId?parents.FindIndex(x=>x.Id==parentId)+1:0};var track=Entry("Department / track",m?.Track??"Main event");var location=Entry("Location",m?.Location??"");var status=new Picker {Title="Progress",ItemsSource=new[]{"Planned","In progress","Complete","Blocked"},SelectedItem=m?.Status??"Planned"};var notes=new Editor {Text=m?.Notes??"",Placeholder="Instructions and backup plan",HeightRequest=100};foreach(var view in new View[]{title,who,Label("Day"),day,Label("Start time (24 hour)"),time,duration,artist,Label("Slot type"),kind,Label("Show in guest programme"),programme,track,location,status,dependency,notes}){if(!show&&(view==artist||view==kind||view==programme||view is Label lab&&(lab.Text=="Slot type"||lab.Text=="Show in guest programme")))continue;form.Add(view);}form.Add(Button("Save moment",async()=>{var item=new Moment {Id=m?.Id??Guid.NewGuid()};item.Graph=m?.Graph;item.Title=title.T