    private void DrawTasks(){var e=_event!;_body.Add(Button("Add a task",async()=>{var title=await DisplayPromptAsync("Add task","What needs doing?");if(string.IsNullOrWhiteSpace(title))return;var who=await DisplayPromptAsync("Responsibility","Who will do it?",initialValue:"Organiser");e.Tasks.Add(new(){Title=title,Who=who??"",Due=e.Start});await _store.SaveAsync(e);Draw();}));foreach(var task in e.Tasks){var row=new Grid {ColumnDefinitions={new ColumnDefinition {Width=GridLength.Auto},new ColumnDefinition {Width=GridLength.Star}},ColumnSpacing=12};var check=new CheckBox {IsChecked=task.Done};check.CheckedChanged+=async(_,args)=>await Run(async()=>{task.Done=args.Value;await _store.SaveAsync(e);});row.Add(check);row.Add(Label(task.Title,16,true),1);_body.Add(row);_body.Add(Label($"{task.Who} · Due {task.Due:dd MMM yyyy}",14));}}
