    private async Task SupplierEditor(Supplier? s=null){var e=_event!;var p=new ContentPage {Title="Supplier"};var form=new VerticalStackLayout {Padding=20,Spacing=12};var name=Entry("Business",s?.Name??"");var service=Entry("Service",s?.Service??"");var email=Entry("Email",s?.Email??"");var phone=Entry("Phone",s?.Phone??"");var cost=Entry("Agreed cost",(s?.Cost??0).ToString(CultureInfo.InvariantCulture));var paid=Entry("Paid",(s?.Paid??0).ToString(CultureInfo.InvariantCulture));var due=new DatePicker {Date=s?.Due??e.Start,Format="dd/MM/yyyy"};var arrival=Entry("Arrival / setup",s?.Arrival??"");foreach(var v in new View[]{name,service,email,phone,cost,paid,Label("Balance due"),due,arrival})form.Add(v);form.Add(Button("Save supplier",async()=>{if(string.IsNullOrWhiteSpace(name.Text))throw new Exception("Enter a supplier name.");var item=s??new();item.Name=name.Text;item.Service=service.Text??"";item.Email=email.Text??"";item.Phone=phone.Text??"";item.Cost=decimal.TryParse(cost.Text,NumberStyles.Number,CultureInfo.InvariantCulture,out var c)?Math.Max(0,c):0;item.Paid=decimal.TryParse(paid.Text,NumberStyles.Number,CultureInfo.InvariantCulture,out var a)?Math.Max(0,a):0;item.Due=due.Date??e.Start;item.Arrival=arrival.Text??"";if(s is null)e.Suppliers.Add(item);await _store.SaveAsync(e);await Navigation.PopAsync();Draw();}));WrapPage(p,form);await Navigation.PushAsync(p);}
    private void DrawTransfer(){_body.Add(Label("Portable event file",20,true));_body.Add(Label("Share or import a .bigday archive. Online invitations, gift pledges and private gallery files are not included."));_body.Add(Button("Export / share event",async()=>{var path=Path.Combine(FileSystem.CacheDirectory,_event!.Id+".bigday");await File.WriteAllTextAsync(path,EventStore.Export(_event));await Share.Default.RequestAsync(new ShareFileRequest {Title=$"Share {ProductBrand.Name} event",File=new ShareFile(path)});}));_body.Add(Button("Import event file",async()=>{var file=await FilePicker.Default.PickAsync(new PickOptions {PickerTitle="Choose a .bigday event file"});if(file is null)return;await using var stream=await file.OpenReadAsync();if(stream.CanSeek&&stream.Length>2_000_000)throw new Exception("Event archive is too large.");using var reader=new StreamReader(stream);var plan=EventStore.Import(await reader.ReadToEndAsync());await _store.SaveAsync(plan);_event=plan;_events=await _store.LoadAsync();Draw();}));_body.Add(Button("Share over the same Wi-Fi",async()=>{var path=Path.Combine(FileSystem.CacheDirectory,_event!.Id+".bigday");await File.WriteAllTextAsync(path,EventStore.Export(_event));if(_transfer is not null)await _transfer.DisposeAsync();_transfer=await BigDayTransfer.StartAsync(path);using var generator=new QRCodeGenerator();using var data=generator.CreateQrCode(_transfer.Link,QRCodeGenerator.ECCLevel.Q);using var code=new PngByteQRCode(data);var png=code.GetGraphic(6);var layout=new VerticalStackLayout {Padding=20,Spacing=15};layout.Add(Label($"Keep both devices on the same Wi-Fi. Scan the QR code or paste the link in {ProductBrand.Name}'s import screen."));layout.Add(new Image {Source=ImageSource.FromStream(()=>new MemoryStream(png)),HeightRequest=260});layout.Add(new Editor {Text=_transfer.Link,IsReadOnly=true,HeightRequest=100});layout.Add(Button("Copy transfer link",()=>Clipboard.Default.SetTextAsync(_transfer.Link)));var page=new ContentPage {Title="Wi-Fi transfer"};WrapPage(page,layout);page.Disappearing+=async(_,_)=>{if(_transfer is not null){await _transfer.DisposeAsync();_transfer=null;}};await Navigation.PushAsync(page);}));_body.Add(Button("Import from transfer link",async()=>{var link=await DisplayPromptAsync("Wi-Fi transfer","Paste the secure transfer link.");if(string.IsNullOrWhiteSpace(link))return;var path=Path.Combine(FileSystem.CacheDirectory,Guid.NewGuid()+".bigday");await BigDayTransfer.DownloadAsync(link,path);var plan=EventStore.Import(await File.ReadAllTextAsync(path));await _store.SaveAsync(plan);_event=plan;_events=await _store.LoadAsync();Draw();}));}
