    private async Task NavigateTo(string tab){_tab=tab;if(Navigation.NavigationStack.Count>1)await Navigation.PopToRootAsync();Draw();}
    private void WrapPage(ContentPage page,VerticalStackLayout body)
    {
        page.BackgroundColor=Color.FromArgb("#f4f8fa");NavigationPage.SetHasNavigationBar(page,false);LabelFields(body);
        var grid=new Grid {RowDefinitions={new RowDefinition {Height=GridLength.Auto},new RowDefinition {Height=GridLength.Star}},ColumnDefinitions={new ColumnDefinition {Width=new GridLength(230)},new ColumnDefinition {Width=GridLength.Star}}};
        var side=new VerticalStackLayout {Spacing=8,Padding=16,BackgroundColor=Colors.White};side.Add(Label("YOUR ORGANISER",14,true));side.Add(Button(ProductBrand.NewEvent,async()=>{if(Navigation.NavigationStack.Count>1)await Navigation.PopToRootAsync();await EventEditor();}));
        foreach(var tab in (ProductBrand.IsLive?new[]{"Overview","Bands & stages","Running order","Daily critical path","Checklists","Suppliers","Share & import","Online workspace"}:new[]{"Overview","Day plan","Daily critical path","Checklists","Suppliers","Share & import","Online workspace"}))side.Add(Button(tab,()=>NavigateTo(tab)));
        side.Add(Label("Edits are saved with the Save button. Back or a menu choice leaves the form without saving.",14));var sideScroll=new ScrollView {Content=side,VerticalScrollBarVisibility=ScrollBarVisibility.Always};grid.Add(sideScroll,0,1);
        var scroll=new ScrollView {Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Always,HorizontalScrollBarVisibility=ScrollBarVisibility.Default};grid.Add(scroll,1,1);
        var header=new Grid {Padding=12,ColumnSpacing=12,BackgroundColor=Color.FromArgb(ProductBrand.Header),ColumnDefinitions={new ColumnDefinition {Width=GridLength.Auto},new ColumnDefinition {Width=GridLength.Auto},new ColumnDefinition {Width=GridLength.Star}}};
        var back=Button("Back",async()=>{if(page!=this)await Navigation.PopAsync();else await NavigateTo("Overview");});header.Add(back,0);var menu=Button("Menu",()=>{sideScroll.IsVisible=!sideScroll.IsVisible;grid.ColumnDefinitions[0].Width=sideScroll.IsVisible?new GridLength(230):new GridLength(0);return Task.CompletedTask;});header.Add(menu,1);
        var brand=new HorizontalStackLayout {Spacing=10,VerticalOptions=LayoutOptions.Center};brand.Add(new Image {Source="brandmark.png",WidthRequest=34,HeightRequest=34});brand.Add(new Label {Text=page==this?ProductBrand.Name:page.Title,TextColor=Colors.White,FontSize=21,FontAttributes=FontAttributes.Bold,VerticalOptions=LayoutOptions.Center});header.Add(brand,2);grid.Add(header);Grid.SetColumnSpan(header,2);
        var lastWide=false;page.SizeChanged+=(_,_)=>{var wide=page.Width>=900;if(wide!=lastWide){lastWide=wide;sideScroll.IsVisible=wide;grid.ColumnDefinitions[0].Width=wide?new GridLength(230):new GridLength(0);}};sideScroll.IsVisible=false;grid.ColumnDefinitions[0].Width=new GridLength(0);page.Content=grid;
    }
    private static void LabelFields(VerticalStackLayout form){var fields=form.Children.ToList();form.Clear();foreach(var view in fields){string? title=view switch {Entry e=>e.Placeholder,Editor e=>e.Placeholder,Picker e=>e.Title,_=>null};if(view is VisualElement element&&!element.IsVisible)continue;if(!string.IsNullOrWhiteSpace(title)&&(form.Children.LastOrDefault() is not Label last||last.Text!=title))form.Add(Label(title,16,true));if(view is VerticalStackLayout child)LabelFields(child);form.Add(view);}}
    private void DrawCritical()
    {
        var e=_event!;var days=e.Timeline.Select(x=>x.Day.Date).Distinct().OrderBy(x=>x).ToList();if(days.Count==0){_body.Add(Label("Add running-order moments to build a daily path."));return;}
        if(_criticalDay is null||!days.Contains(_criticalDay.Value))_criticalDay=days[0];var day=_criticalDay.Value;var dayPicker=new Picker {Title="Choose day",ItemsSource=days.Select(x=>x.ToString("dd MMM yyyy")).ToList(),SelectedIndex=days.IndexOf(day)};dayPicker.SelectedIndexChanged+=(_,_)=>{if(dayPicker.SelectedIndex>=0){_criticalDay=days[dayPicker.SelectedIndex];Draw();}};_body.Add(dayPicker);
        var areas=new[]{"All areas"}.Concat(e.Timeline.Where(x=>x.Day.Date==day).Select(x=>x.Location).Where(x=>x.Length>0).Distinct()).ToList();if(_criticalArea!=""&&!areas.Contains(_criticalArea))_criticalArea="";var areaPicker=new Picker {Title="Stage / area",ItemsSource=areas,SelectedIndex=Math.Max(0,areas.IndexOf(_criticalArea==""?"All areas":_criticalArea))};areaPicker.SelectedIndexChanged+=(_,_)=>{_criticalArea=areaPicker.SelectedIndex>0?areas[areaPicker.SelectedIndex]:"";Draw();};_body.Add(areaPicker);
        _body.Add(Label("The longest dependency chain uses durations, excluding waiting gaps. Drag a card before another, or use Move up/down. This reschedules the chosen day/area consecutively, keeping dependencies. Review warnings.",14));
        CriticalResult result;try{result=CriticalPath.Calculate(e,day);}catch(Exception error){_body.Add(Label(error.Message,16,true));return;}_body.Add(Label($"Longest chain: {result.Length} minutes",22,true));foreach(var warning in result.Warnings)_body.Add(Label("Check: "+warning,14,true));
        _body.Add(Button(_criticalGraph?"Show detailed list":"Show dependency graph",()=>{_criticalGraph=!_criticalGraph;Draw();return Task.CompletedTask;}));
        if(_criticalGraph)
        {
            _body.Add(Label("Amber cards and arrows show critical activities. Arrows point from prerequisite to next activity. Dashed cards are dependencies from another area. The longest chain covers the whole day. Drag Move or the resize corner. Positions save locally. Use the detailed list to edit timings or reorder.",14));
            var graph=new WebView {HeightRequest=480,Source=new HtmlWebViewSource {Html=CriticalGraph.Html(result,_criticalArea,_graphZoom)}};
            graph.Navigating+=async(_,args)=>
            {
                if(!args.Url.StartsWith("sortedgraph://save?data=",StringComparison.Ordinal))return;args.Cancel=true;
                try
                {
                    using var payload=System.Text.Json.JsonDocument.Parse(Uri.UnescapeDataString(args.Url.Split("?data=",2)[1]));
                    var root=payload.RootElement;var id=root.GetProperty("id").GetGuid();var moment=e.Timeline.FirstOrDefault(m=>m.Id==id&&m.Day.Date==day);
                    if(moment is null)throw new InvalidOperationException("Graph activity not found.");
                    var old=moment.Graph;moment.Graph=GraphBox.Parse(root.GetProperty("box"));try{await _store.SaveAsync(e);}catch{moment.Graph=old;throw;}
                    await graph.EvaluateJavaScriptAsync("window.sortedGraphSaved(true)");
                }
                catch {await graph.EvaluateJavaScriptAsync("window.sortedGraphSaved(false)");}
            };
            var zoomLabel=Label($"Zoom: {_graphZoom:P0}",14,true);var zoom=new Slider {Minimum=.5,Maximum=2,Value=_graphZoom};
            zoom.ValueChanged+=(_,args)=>{_graphZoom=args.NewValue;zoomLabel.Text=$"Zoom: {_graphZoom:P0}";graph.Source=new HtmlWebViewSource {Html=CriticalGraph.Html(result,_criticalArea,_graphZoom)};};
            _body.Add(zoomLabel);_body.Add(zoom);_body.Add(graph);return;
        }
        var rows=result.Nodes.Where(x=>_criticalArea==""||x.Moment.Location==_criticalArea).OrderBy(x=>x.Moment.Time).ToList();
        async Task Move(Guid source,Guid target){CriticalPath.MoveBefore(e,day,_criticalArea,source,target);await _store.SaveAsync(e);Draw();}
        for(int i=0;i<rows.Count;i++){var index=i;var node=rows[i];var moment=node.Moment;var card=new VerticalStackLayout {Padding=18,Spacing=10,BackgroundColor=node.IsCritical?Color.FromArgb("#fff2dd"):Colors.White};card.Add(Label(node.IsCritical?"CRITICAL":"Float: "+node.Float+" min",14,true));card.Add(Label($"{moment.Time:hh\\:mm} · {moment.Title}",19,true));card.Add(Label($"{moment.Duration} min · {moment.Location} · {moment.Who}"));if(moment.DependsOn is Guid pid)card.Add(Label("After: "+(e.Timeline.FirstOrDefault(x=>x.Id==pid)?.Title??"Missing dependency"),14));
            if(i>0)card.Add(Button("Move up",()=>Move(moment.Id,rows[index-1].Moment.Id)));if(i<rows.Count-1)card.Add(Button("Move down",()=>Move(rows[index+1].Moment.Id,moment.Id)));card.Add(Button("Edit / dependency",()=>MomentEditor(moment)));
            var drag=new DragGestureRecognizer {CanDrag=true};drag.DragStarting+=(_,args)=>args.Data.Properties["BigDayMoment"]=moment.Id;var drop=new DropGestureRecognizer {AllowDrop=true};drop.Drop+=async(_,args)=>await Run(async()=>{if(args.Data.Properties.TryGetValue("BigDayMoment",out var value)&&value is Guid source)await Move(source,moment.Id);});card.GestureRecognizers.Add(drag);card.GestureRecognizers.Add(drop);_body.Add(card);
        }
    }

}
